 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Each vertical ray is defined by 5 endpoints at the bottom. Every
    # existing colored cell on that column propagates away from the 5s,
    # with nearest colored seed taking precedence (downward propagation).
    for c in range(w):
        if grid[h - 1][c] != 5:
            continue
        # In demos, the bottom 5 segment runs up to the lowest seed; above
        # the highest seed, that seed's color propagates upward.
        seeds = [r for r in range(h - 1) if grid[r][c] != 0]
        if not seeds:
            continue
        low = max(seeds)
        high = min(seeds)
        for r in range(h - 1, low, -1):
            if grid[r][c] == 0:
                out[r][c] = 5
        for r in range(high - 1, -1, -1):
            if grid[r][c] == 0:
                out[r][c] = grid[high][c]
        # Between seed cells, fill with the color of the lower seed.
        for a, b in zip(seeds, seeds[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == 0:
                    out[r][c] = grid[b][c]
    return out

if __name__ == '__main__':
    import sys
    grid = [list(map(int, line.split())) for line in sys.stdin if line.strip()]
    for row in transform(grid):
        print(' '.join(map(str, row)))
